string = input()
n = len(string)
stack = []
mapping = [0] * n
for (idx, char) in enumerate(string):
	if char == '(':
		stack.append(idx)
	elif char == ')' and stack:
		mapping[stack.pop()] = idx
i = 0
mx = 0
cnt = 1
tmp_max = 0
prev_join_idx = 0
while i < n:
	if mapping[i]:
		curr_len = mapping[i] - i + 1
		if i == prev_join_idx + 1:
			tmp_max += curr_len
		else:
			tmp_max = curr_len
		if tmp_max > mx:
			mx = tmp_max
			cnt = 1
		elif tmp_max == mx:
			cnt += 1
		prev_join_idx = mapping[i]
		i = mapping[i] + 1
	else:
		i += 1
print(mx, cnt)
